package com.gameaggregator.ledgerservice.domain;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;import java.util.UUID;@Entity @Table(name="settlements") public class Settlement{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID beneficiaryId;@Column(nullable=false)public LocalDate periodFrom;@Column(nullable=false)public LocalDate periodTo;@Column(nullable=false,precision=19,scale=6)public BigDecimal amount;@Column(nullable=false)public String status="PENDING";@Column(nullable=false)public Instant createdAt=Instant.now();protected Settlement(){}public Settlement(UUID b,LocalDate f,LocalDate t,BigDecimal a){beneficiaryId=b;periodFrom=f;periodTo=t;amount=a;}}